 * URI reference parsing, normalization and resolution per RFC 3986.
 */

export class UriError extends Error {
  constructor(message) {
    super(message)
    this.name = 'UriError'
  }
}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

/**
 * Parse a URI reference into { scheme, authority, path, query, fragment }.
 * scheme and authority are strings or null when absent; path is always a
 * string; query and fragment are strings or null when absent.
 */
export function parseUri(s) {
  let rest = s
  let scheme = null

  let colonIdx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      colonIdx = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIdx >= 0) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    let i = 2
    while (i < rest.length && rest[i] !== '/' && rest[i] !== '?' && rest[i] !== '#') i++
    authority = rest.slice(2, i)
    rest = rest.slice(i)
  }

  let firstIdx = -1
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '?' || rest[i] === '#') {
      firstIdx = i
      break
    }
  }

  let path
  let query = null
  let fragment = null

  if (firstIdx === -1) {
    path = rest
  } else {
    path = rest.slice(0, firstIdx)
    if (rest[firstIdx] === '?') {
      const hIdx = rest.indexOf('#', firstIdx + 1)
      if (hIdx === -1) {
        query = rest.slice(firstIdx + 1)
      } else {
        query = rest.slice(firstIdx + 1, hIdx)
        fragment = rest.slice(hIdx + 1)
      }
    } else {
      fragment = rest.slice(firstIdx + 1)
    }
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Parse an authority string into { userinfo, host, port }, each a string
 * or null when absent.
 */
export function parseAuthority(authority) {
  let userinfo = null
  let hostport = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    hostport = authority.slice(atIdx + 1)
  }

  const bracketIdx = hostport.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = hostport.indexOf(':', searchFrom)

  let host, port
  if (colonIdx === -1) {
    host = hostport
    port = null
  } else {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
}

function isHexDigit(c) {
  return c !== undefined && /^[0-9a-fA-F]$/.test(c)
}

function isUnreservedByte(val) {
  return (
    (val >= 0x41 && val <= 0x5a) || // A-Z
    (val >= 0x61 && val <= 0x7a) || // a-z
    (val >= 0x30 && val <= 0x39) || // 0-9
    val === 0x2d || // -
    val === 0x2e || // .
    val === 0x5f || // _
    val === 0x7e // ~
  )
}

/**
 * Normalize percent-encodings in a component string. Throws UriError
 * (without a component name attached) when a `%` is not followed by two
 * hex digits.
 */
export function normalizePercentEncoding(s) {
  let result = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '%') {
      const h1 = s[i + 1]
      const h2 = s[i + 2]
      if (!isHexDigit(h1) || !isHexDigit(h2)) {
        throw new UriError('truncated percent-encoding')
      }
      const hex = (h1 + h2).toUpperCase()
      const val = parseInt(hex, 16)
      if (isUnreservedByte(val)) {
        result += String.fromCharCode(val)
      } else {
        result += '%' + hex
      }
      i += 2
    } else {
      result += c
    }
  }
  return result
}

function lowercaseAscii(s) {
  let result = ''
  for (const c of s) {
    if (c >= 'A' && c <= 'Z') result += c.toLowerCase()
    else result += c
  }
  return result
}

/**
 * Remove dot segments from a path per RFC 3986 section 5.2.4.
 */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  const removeLastSegment = () => {
    const idx = output.lastIndexOf('/')
    output = idx === -1 ? '' : output.slice(0, idx)
  }

  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      removeLastSegment()
    } else if (input === '/..') {
      input = '/'
      removeLastSegment()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }

  return output
}

/**
 * Normalize a parsed URI reference ({ scheme, authority, path, query,
 * fragment }) into its string form. Throws UriError with a `component`
 * property set to the failing component's name when a percent-encoding
 * is truncated.
 */
export function normalizeComponents(components) {
  let { scheme, authority, path, query, fragment } = components

  if (scheme !== null) {
    scheme = lowercaseAscii(scheme)
  }

  let userinfo = null
  let host = null
  let port = null
  if (authority !== null) {
    const parsed = parseAuthority(authority)
    userinfo = parsed.userinfo
    host = parsed.host
    port = parsed.port
  }

  const order = [
    ['userinfo', () => userinfo, (v) => (userinfo = v)],
    ['host', () => host, (v) => (host = v)],
    ['path', () => path, (v) => (path = v)],
    ['query', () => query, (v) => (query = v)],
    ['fragment', () => fragment, (v) => (fragment = v)],
  ]

  for (const [name, get, set] of order) {
    const value = get()
    if (value === null) continue
    try {
      set(normalizePercentEncoding(value))
    } catch (e) {
      const err = new UriError(`the ${name} has a truncated percent-encoding`)
      err.component = name
      throw err
    }
  }

  if (host !== null) {
    host = lowercaseAscii(host)
  }

  if (authority !== null && port !== null) {
    const defaultPort = scheme !== null ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || (defaultPort !== undefined && port === defaultPort)) {
      port = null
    }
  }

  path = removeDotSegments(path)

  if (authority !== null && path === '') {
    path = '/'
  }

  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (authority !== null) {
    out += '//'
    if (userinfo !== null) out += userinfo + '@'
    if (host !== null) out += host
    if (port !== null) out += ':' + port
  }
  out += path
  if (query !== null) out += '?' + query
  if (fragment !== null) out += '#' + fragment

  return out
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolve a reference against a base per RFC 3986 section 5.2.2 (strict).
 * Both base and ref are parsed URI components; base.scheme must not be
 * null. Returns a parsed components object, not yet normalized.
 */
export function resolveReference(base, ref) {
  let result

  if (ref.scheme !== null) {
    result = {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.authority !== null) {
    result = {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.path === '') {
    result = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
    }
  } else {
    let path
    if (ref.path.startsWith('/')) {
      path = removeDotSegments(ref.path)
    } else {
      path = removeDotSegments(mergePaths(base, ref.path))
    }
    result = {
      scheme: base.scheme,
      authority: base.authority,
      path,
      query: ref.query,
    }
  }

  result.fragment = ref.fragment
  return result
}
"}

